import unittest

from stocklib.ledger import Ledger
from stocklib.report import summary
from stocklib.textutil import slugify
from stocklib.units import convert


class LedgerTest(unittest.TestCase):
    def test_add_and_remove(self):
        ledger = Ledger()
        ledger.add("bolt", 5)
        ledger.remove("bolt", 2)
        self.assertEqual(ledger.quantity("bolt"), 3)

    def test_non_positive_quantities_are_refused(self):
        ledger = Ledger()
        with self.assertRaises(ValueError):
            ledger.add("bolt", 0)
        with self.assertRaises(ValueError):
            ledger.remove("bolt", -1)


class UnitsTest(unittest.TestCase):
    def test_kilograms_to_grams(self):
        self.assertEqual(convert(2, "kg", "g"), 2000)

    def test_unknown_unit(self):
        with self.assertRaises(ValueError):
            convert(1, "stone", "g")


class ReportTest(unittest.TestCase):
    def test_summary_lists_each_sku(self):
        ledger = Ledger()
        ledger.add("nut", 2)
        ledger.add("bolt", 1)
        self.assertIn("bolt: 1", summary(ledger))
        self.assertIn("nut: 2", summary(ledger))


class TextTest(unittest.TestCase):
    def test_slugify(self):
        self.assertEqual(slugify("  Hello, World! "), "hello-world")

