class Oracle(unittest.TestCase):
    def test_pounds_and_ounces(self):
        self.assertAlmostEqual(convert(1, "lb", "g"), 453.59237, places=9)
        self.assertAlmostEqual(convert(16, "oz", "lb"), 1.0, places=9)
